/**
 * codex-command-runner 帧 IPC 客户端（Windows 命名管道）。
 *
 * 对 PDF 层 json:speak `codex ipc_framed`：父进程建两条命名管道（`<nonce>-in` / `-out`），
 * 拉起 codex-command-runner（`--pipe-in` / `--pipe-out`），runner 先连 in 后连 out；
 * 父进程向 in 写 `SpawnRequest` 帧、从 out 读 `spawn_ready`/`output`/`exit`/`error` 帧。
 * 帧 = 4 字节小端长度 + UTF-8 JSON。stdout 经默认 ConPTY 以 ANSI 字节返回。
 * 协议版本 = `{ "version": 6 }`（release 二进制 IPC_PROTOCOL_VERSION）。
 * @module
 */

import { createServer, type Server, type Socket } from 'node:net'
import { spawn } from 'node:child_process'
import { randomBytes } from 'node:crypto'

/** 命名管道全名：`\\.\pipe\tpt-sandbox-<nonce>-in` / `-out`。管道名由我方自造（runner 只从
 *  `--pipe-in/--pipe-out` 拿完整路径），所以改名不涉及与已签名 exe 的协议字段。 */
export function pipePair(prefix = 'tpt-sandbox'): { in: string; out: string; nonce: string } {
  const nonce = `${prefix}-${randomBytes(6).toString('hex')}`
  return { in: `\\\\.\\pipe\\${nonce}-in`, out: `\\\\.\\pipe\\${nonce}-out`, nonce }
}

/** 单个监管目录条目的 PathValue（codex permission_profile file_system 的 path 字段）。 */
export type ProfilePath =
  | { type: 'special'; value: { kind: 'root' | 'project_roots' | 'slash_tmp' | 'tmpdir' | 'minimal' } }
  | { type: 'path'; path: string }

/** file_system 权限条目的能力值。 */
export type PermissionAccess = 'read' | 'write' | 'deny'

/** codex PermissionProfile（managed + restricted file_system + restricted network）。 */
export interface PermissionProfile {
  type: 'managed'
  file_system: { type: 'restricted'; entries: Array<{ path: ProfilePath; access: PermissionAccess }> }
  network: 'restricted'
}

/** 由调用方 argv/cwd/env/permission_profile/workspace_roots/cap_sids 组成的 SpawnRequest。 */
export interface SpawnRequest {
  command: string[]
  cwd: string
  env: Record<string, string>
  permission_profile: PermissionProfile
  workspace_roots: string[]
  codex_home: string
  real_codex_home: string
  cap_sids: string[]
  timeout_ms?: number | undefined
  tty: boolean
  stdin_open: boolean
  use_private_desktop: boolean
}

const IPC_PROTOCOL_VERSION = 6

/** 写一帧（4 字节 LE 长度 + JSON）。单次合并写入，避免命名管道按消息边界拆开发送。 */
function writeFrameBytes(socket: Socket, payload: unknown): void {
  const json = JSON.stringify(payload)
  const bytes = Buffer.from(json, 'utf8')
  const head = Buffer.alloc(4)
  head.writeUInt32LE(bytes.length, 0)
  socket.write(Buffer.concat([head, bytes]))
}

/** 构造 spawn_request 顶层帧。 */
export function spawnRequestFrame(request: SpawnRequest): string {
  return JSON.stringify({
    version: IPC_PROTOCOL_VERSION,
    type: 'spawn_request',
    payload: request,
  })
}

/** 向子进程 stdin 写一帧（data 以 base64 编码）。 */
export function stdinFrame(data: Uint8Array): string {
  return JSON.stringify({
    version: IPC_PROTOCOL_VERSION,
    type: 'stdin',
    payload: { data_b64: Buffer.from(data).toString('base64') },
  })
}

/** 关闭子进程 stdin（EOF）。 */
export function closeStdinFrame(): string {
  return JSON.stringify({ version: IPC_PROTOCOL_VERSION, type: 'close_stdin', payload: {} })
}

/** 调整 ConPTY 尺寸。 */
export function resizeFrame(rows: number, cols: number): string {
  return JSON.stringify({ version: IPC_PROTOCOL_VERSION, type: 'resize', payload: { rows, cols } })
}

/** 终止子进程。 */
export function terminateFrame(): string {
  return JSON.stringify({ version: IPC_PROTOCOL_VERSION, type: 'terminate', payload: {} })
}

/** 一个已解析的输出帧。 */
export type RunnerFrame =
  | { type: 'spawn_ready'; process_id: number }
  | { type: 'output'; data: Buffer; stream: 'stdout' | 'stderr' }
  | { type: 'exit'; exit_code: number; timed_out: boolean }
  | { type: 'error'; message: string; stage?: string; windows_error_code?: number }

/** 累积从 out 管道读到的字节并按帧边界切分。 */
export function frameDecoder(): {
  feed(chunk: Buffer): RunnerFrame[]
  remainder(): Buffer
} {
  let buf = Buffer.alloc(0)
  return {
    feed(chunk: Buffer): RunnerFrame[] {
      buf = Buffer.concat([buf, chunk])
      const frames: RunnerFrame[] = []
      for (;;) {
        if (buf.length < 4) break
        const len = buf.readUInt32LE(0)
        if (buf.length < 4 + len) break
        const json = buf.subarray(4, 4 + len).toString('utf8')
        buf = buf.subarray(4 + len)
        const parsed = JSON.parse(json) as {
          type: string
          payload?: { process_id?: number; data_b64?: string; stream?: string; exit_code?: number; timed_out?: boolean; message?: string; stage?: string; windows_error_code?: number }
        }
        const p = parsed.payload
        if (parsed.type === 'spawn_ready') {
          frames.push({ type: 'spawn_ready', process_id: p?.process_id ?? 0 })
        } else if (parsed.type === 'output' && p?.data_b64 !== undefined) {
          frames.push({
            type: 'output',
            data: Buffer.from(p.data_b64, 'base64'),
            stream: p.stream === 'stderr' ? 'stderr' : 'stdout',
          })
        } else if (parsed.type === 'exit') {
          frames.push({ type: 'exit', exit_code: p?.exit_code ?? 0, timed_out: p?.timed_out ?? false })
        } else if (parsed.type === 'error') {
          const errorFrame: RunnerFrame = {
            type: 'error',
            message: p?.message ?? '(no message)',
          }
          if (p?.stage !== undefined) errorFrame.stage = p.stage
          if (p?.windows_error_code !== undefined) errorFrame.windows_error_code = p.windows_error_code
          frames.push(errorFrame)
        }
      }
      return frames
    },
    remainder() {
      return buf
    },
  }
}

/** 一次 runner 会话：双管道连接 + 帧读写。 */
export interface RunnerSession {
  /** 向 runner 写一帧（通常先发 spawn_request）。 */
  send(request: SpawnRequest): void
  /** 订阅帧；返回退订函数。 */
  onFrame(listener: (frame: RunnerFrame) => void): () => void
  /** 会话结束（管道关闭）后的 Promise。 */
  done(): Promise<void>
  /** 终止 runner 子进程（尽力而为）。 */
  kill(): void
}

/** 打开两条 pipe server 并等待 runner 连接；返回可读写侧与 runner 子进程。 */
export interface RunnerLaunch {
  session: RunnerSession
  runnerProc: ReturnType<typeof spawn>
}

function refuseNonWindows(): never {
  throw new Error('tpt-sandbox: this IPC client is Windows-only (named pipes + sandbox-runner.exe)')
}

/**
 * 拉起初会话：建双命名管道 → spawn codex-command-runner → 等 runner 连上两条管道。
 *
 * 提权（以沙箱用户拉起 runner）需 CreateProcessWithLogonW，Node 无法直调；`elevateRunnerCmd`
 * 传入后改用已编译的提权 helper（见 elevation.ts），否则以当前用户直接 spawn（非提权路径，
 * 仅有 codex LUA 限权、无写隔离——见 research/codex-command-runner-de-risked-no-isolation-non-elevated；帮隔离需提权）。
 */
export async function launchRunner(options: {
  runnerExe: string
  cwd: string
  log?: (line: string) => void
  launchArgs?: string[]
}): Promise<RunnerLaunch> {
  if (process.platform !== 'win32') refuseNonWindows()
  const { in: inName, out: outName } = pipePair()
  const log = options.log ?? (() => {})
  const pipes = { in: inName, out: outName }

  const connect = (name: string): Promise<Socket> =>
    new Promise((resolve, reject) => {
      const server: Server = createServer((socket: Socket) => {
        server.close()
        resolve(socket)
      })
      server.on('error', reject)
      server.listen(name, () => {})
    })

  const inConnect = connect(pipes.in)
  const outConnect = connect(pipes.out)

  const runnerProc = spawn(options.runnerExe, [...(options.launchArgs ?? []), `--pipe-in=${pipes.in}`, `--pipe-out=${pipes.out}`], {
    cwd: options.cwd,
    windowsHide: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  })
  runnerProc.stdout?.on('data', (c: Buffer) => log(c.toString('utf8')))
  runnerProc.stderr?.on('data', (c: Buffer) => log(c.toString('utf8')))

  const [pipeIn, pipeOut] = await Promise.all([inConnect, outConnect])

  const listeners = new Set<(frame: RunnerFrame) => void>()
  const decoder = frameDecoder()
  const sessionDone = new Promise<void>((resolve) => {
    pipeOut.on('end', () => resolve())
    pipeOut.on('close', () => resolve())
  })

  pipeOut.on('data', (chunk: Buffer) => {
    log(`tpt-sandbox: frame bytes=${chunk.length}`)
    for (const frame of decoder.feed(chunk)) {
      // 快照后再派发：listener 自己可能在回调里 unsubscribe（改动的正是这个数组），直接迭代活
      // 数组会跳条目或重入。这里的拷贝是必需的，不是冗余展开。
      for (const listener of Array.from(listeners)) listener(frame)
    }
  })

  const session: RunnerSession = {
    send(request) {
      writeFrameBytes(pipeIn, request)
    },
    onFrame(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    done() {
      return sessionDone
    },
    kill() {
      try {
        runnerProc.kill('SIGKILL')
      } catch {
        /* 尽力而为 */
      }
      pipeIn.destroy()
      pipeOut.destroy()
    },
  }

  return { session, runnerProc }
}
